// Calcula fecha de ayer, la agrega a cada cliente.
const d = new Date();
d.setDate(d.getDate() - 1);
const yesterday = d.toISOString().split('T')[0];

return $input.all().map(item => ({
  json: {
    ...item.json,
    yesterday
  }
}));

// Aplana la respuesta de Meta manteniendo el sheet_id de cada cliente.
const pick = (arr, key) => {
  if (!Array.isArray(arr)) return 0;
  const found = arr.find(a => a.action_type === key);
  return found ? parseFloat(found.value) : 0;
};
const pickAny = (arr, keys) => {
  for (const k of keys) {
    const v = pick(arr, k);
    if (v > 0) return v;
  }
  return 0;
};

const rows = [];

for (const item of $input.all()) {
  // sheet_id viene de la iteración del cliente (Master Sheet)
  const sheetId = item.json.sheet_id || item.json['Sheet ID'];
  const data = item.json.data || [];

  for (const r of data) {
    const spend = parseFloat(r.spend || 0);
    const compras = pickAny(r.actions, ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase']);
    const valorCompra = pickAny(r.action_values, ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase']);
    const costoCompra = pickAny(r.cost_per_action_type, ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase']);
    const atc = pickAny(r.actions, ['add_to_cart', 'offsite_conversion.fb_pixel_add_to_cart']);
    const valorAtc = pickAny(r.action_values, ['add_to_cart', 'offsite_conversion.fb_pixel_add_to_cart']);
    const costoAtc = pickAny(r.cost_per_action_type, ['add_to_cart', 'offsite_conversion.fb_pixel_add_to_cart']);
    const ic = pickAny(r.actions, ['initiate_checkout', 'offsite_conversion.fb_pixel_initiate_checkout']);
    const valorIc = pickAny(r.action_values, ['initiate_checkout', 'offsite_conversion.fb_pixel_initiate_checkout']);
    const costoIc = pickAny(r.cost_per_action_type, ['initiate_checkout', 'offsite_conversion.fb_pixel_initiate_checkout']);
    const lpv = pick(r.actions, 'landing_page_view');
    const costoLpv = pick(r.cost_per_action_type, 'landing_page_view');

    let roas = 0;
    if (Array.isArray(r.purchase_roas) && r.purchase_roas.length) {
      roas = parseFloat(r.purchase_roas[0].value);
    } else if (spend > 0) {
      roas = valorCompra / spend;
    }

    rows.push({
      json: {
        _sheet_id: sheetId,
        unique_id: `${r.date_start}_${r.ad_id}`,
        fecha: r.date_start,
        campaign_id: r.campaign_id,
        campaign_name: r.campaign_name,
        adset_id: r.adset_id,
        adset_name: r.adset_name,
        ad_id: r.ad_id,
        ad_name: r.ad_name,
        gasto: spend,
        cpc: parseFloat(r.cpc || 0),
        ctr_general: parseFloat(r.ctr || 0),
        ctr_enlace: parseFloat(r.inline_link_click_ctr || 0),
        frecuencia: parseFloat(r.frequency || 0),
        visitas_pagina: lpv,
        costo_visita_pagina: costoLpv,
        agregados_carrito: atc,
        costo_agregado_carrito: costoAtc,
        valor_agregado_carrito: valorAtc,
        pagos_iniciados: ic,
        costo_pago_iniciado: costoIc,
        valor_pago_iniciado: valorIc,
        compras: compras,
        valor_compra: valorCompra,
        costo_compra: costoCompra,
        roas: roas
      }
    });
  }
}

return rows;
